
"""Parse and validate the final answer generated by the agent."""

import json


VALID_STATUSES = {
    "answered",
    "clarification_needed",
    "unsupported",
    "error",
}

VALID_ANSWER_TYPES = {
    "number",
    "boolean",
    "node",
    "node_list",
    "path",
    "text",
}


def _fallback_answer(raw_text):
    """Handle responses that are not valid JSON."""

    text = (raw_text or "").strip()

    return {
        "status": "answered",
        "answer_text": text,
        "answer": {
            "type": "text",
            "value": text,
        },
    }


def parse_answer(raw_text):
    """
    Parse the agent's final response into the required structure.

    Expected JSON:
    {
        "status": "answered",
        "answer_text": "...",
        "answer": {
            "type": "number",
            "value": 34
        }
    }
    """

    if not isinstance(raw_text, str) or not raw_text.strip():
        return {
            "status": "error",
            "answer_text": "The agent returned an empty response.",
            "answer": {
                "type": "text",
                "value": "",
            },
        }

    # Attempt to parse the response as JSON.
    try:
        parsed = json.loads(raw_text.strip())

    except json.JSONDecodeError:
        return _fallback_answer(raw_text)

    # The JSON response must be an object.
    if not isinstance(parsed, dict):
        return _fallback_answer(raw_text)

    status = parsed.get("status")
    answer_text = parsed.get("answer_text")
    answer = parsed.get("answer")

    # Validate status.
    if status not in VALID_STATUSES:
        return _fallback_answer(raw_text)

    # Validate answer_text.
    if not isinstance(answer_text, str):
        return _fallback_answer(raw_text)

    # Error and unsupported responses may not have a structured answer.
    if status in {"error", "unsupported", "clarification_needed"}:
        if answer is None:
            answer = {
                "type": "text",
                "value": answer_text,
            }

        elif not isinstance(answer, dict):
            return _fallback_answer(raw_text)

        return {
            "status": status,
            "answer_text": answer_text,
            "answer": answer,
        }

    # An answered response must contain a structured answer.
    if not isinstance(answer, dict):
        return _fallback_answer(raw_text)

    answer_type = answer.get("type")
    answer_value = answer.get("value")

    if answer_type not in VALID_ANSWER_TYPES:
        return _fallback_answer(raw_text)

    if "value" not in answer:
        return _fallback_answer(raw_text)

    # Validate values according to their answer types.
    if answer_type == "number":
        if (
            isinstance(answer_value, bool)
            or not isinstance(answer_value, (int, float))
        ):
            return _fallback_answer(raw_text)

    elif answer_type == "boolean":
        if not isinstance(answer_value, bool):
            return _fallback_answer(raw_text)

    elif answer_type == "node":
        if not isinstance(answer_value, str):
            return _fallback_answer(raw_text)

    elif answer_type in {"node_list", "path"}:
        if not isinstance(answer_value, list):
            return _fallback_answer(raw_text)

    elif answer_type == "text":
        if not isinstance(answer_value, str):
            return _fallback_answer(raw_text)

    return {
        "status": status,
        "answer_text": answer_text,
        "answer": {
            "type": answer_type,
            "value": answer_value,
        },
    }
